-- Multi-subject Brain Heist canonical skill registries with Cambridge programme crosswalks.
-- Canonical identity belongs to Brain Heist. External framework references remain crosswalk metadata.

create table if not exists public.academic_skill_registry_subject_aliases(
  id uuid primary key default gen_random_uuid(),
  alias_normalized text not null unique,
  registry_version_id uuid not null references public.academic_skill_registry_versions(id) on delete restrict,
  allowed_strand_codes text[],
  display_name text,
  status text not null default 'active' check(status in ('active','retired')),
  created_at timestamptz not null default now()
);
create index if not exists academic_skill_registry_subject_aliases_registry_idx
  on public.academic_skill_registry_subject_aliases(registry_version_id,status);
alter table public.academic_skill_registry_subject_aliases enable row level security;
revoke all on public.academic_skill_registry_subject_aliases from public,anon,authenticated,service_role;
grant select on public.academic_skill_registry_subject_aliases to authenticated,service_role;
drop policy if exists "Authenticated can read active skill registry subject aliases"
  on public.academic_skill_registry_subject_aliases;
create policy "Authenticated can read active skill registry subject aliases"
  on public.academic_skill_registry_subject_aliases for select to authenticated
  using(status='active' and exists(
    select 1 from public.academic_skill_registry_versions v
    where v.id=registry_version_id and v.status='published'
  ));

