('bh-global-perspectives-core-v1','global-perspectives','Brain Heist Global Perspectives Core Skill Registry v1','Stable transferable inquiry and global-perspectives skills registry.','brain_heist_canonical_with_cambridge_crosswalk','published','2026-09-24'::date),
('bh-mathematics-core-v1','mathematics','Brain Heist Mathematics Core Skill Registry v1','Stable longitudinal mathematics competency registry with Cambridge programme crosswalks.','brain_heist_canonical_with_cambridge_crosswalk','published','2026-09-24'::date),
('bh-modern-languages-core-v1','modern-languages','Brain Heist Modern Languages Core Skill Registry v1','Shared transferable language competency registry for non-English modern languages.','brain_heist_canonical_with_cambridge_crosswalk','published','2026-09-24'::date),
('bh-science-core-v1','science','Brain Heist Science Core Skill Registry v1','Stable longitudinal science competency registry shared by general Science, Biology, Chemistry and Physics.','brain_heist_canonical_with_cambridge_crosswalk','published','2026-09-24'::date),
