insert into public.academic_skill_registry_subject_aliases(
 alias_normalized,registry_version_id,allowed_strand_codes,display_name,status
)
select s.alias_normalized,v.id,s.allowed_strand_codes,s.display_name,s.status
from seed s join public.academic_skill_registry_versions v on v.code=s.version_code
on conflict(alias_normalized) do update set registry_version_id=excluded.registry_version_id,
 allowed_strand_codes=excluded.allowed_strand_codes,display_name=excluded.display_name,status=excluded.status;

